/**
 * Android resource XML for the TWA: the start URL, host, path prefix and the asset_statements JSON Chrome checks on the app side.
 * Generated by gen-resources.mjs; never hand-edited (values come from hub.config.json).
 */
import { deriveTwaUrl } from './twa-url.mjs'

/** Escapes a value for <string> in values/*.xml: XML specials first, then what aapt2 treats as syntax (quotes, leading @ and ?, newlines). */
export function androidString(value) {
  const xml = String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')
  return xml
    .replaceAll('\\', '\\\\')
    .replaceAll('"', '\\"')
    .replaceAll("'", "\\'")
    .replaceAll('\n', '\\n')
    .replace(/^([@?])/, '\\$1')
}

/** The app-to-site half of Digital Asset Links. The file format is https only, so a loopback http origin gets an empty list. */
export function buildAssetStatements(origin) {
  if (!/^https:\/\//.test(origin)) return '[]'
  return JSON.stringify([{ relation: ['delegate_permission/common.handle_all_urls'], target: { namespace: 'web', site: origin } }])
}

/** @param {string} startUrl */
export function buildTwaResourcesXml(startUrl, { allowHttp = false } = {}) {
  const t = deriveTwaUrl(startUrl, { allowHttp })
  const rows = [
    ['default_url', t.startUrl],
    ['twa_host', t.host],
    ['twa_path_prefix', t.pathPrefix],
    ['asset_statements', buildAssetStatements(t.origin)],
  ]
  return [
    '<?xml version="1.0" encoding="utf-8"?>',
    '<!-- generated by android/tools/gen-resources.mjs from hub.config.json: do not edit, do not commit -->',
    '<resources>',
    ...rows.map(([name, v]) => '    <string name="' + name + '" translatable="false">' + androidString(v) + '</string>'),
    '</resources>',
    '',
  ].join('\n')
}
